wwv_flow_imp_shared.create_automation_action(
 p_id=>wwv_flow_imp.id(63348439267749727)
,p_automation_id=>wwv_flow_imp.id(63348072911749687)
,p_name=>'Read them with the OCI reader'
,p_static_id=>'read-with-oci'
,p_execution_sequence=>10
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Watched folder -> OCI reader. Files that arrived from the',
'   folder while WATCH_MODEL was OCI_GENAI wait as UPLOADED with no',
'   read. This sends each one to DLA_PKG.EXTRACT_DOCUMENT (Google',
'   Gemini on OCI). Runs every minute. Logic is in the package;',
'   this action is one call so the repository holds the code. */',
'DECLARE',
'    l_done  NUMBER;',
'BEGIN',
'    l_done := dla_pkg.read_waiting_documents(p_max_documents => 20);',
'    IF l_done > 0 THEN',
'        apex_automation.log_info(''Read '' || l_done || '' waiting document(s) with the OCI reader.'');',
'    END IF;',
'END;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
,p_created_on=>wwv_flow_imp.dz('20261120155731Z')
,p_updated_on=>wwv_flow_imp.dz('20261120155819Z')
,p_created_by=>'GHALL'
,p_updated_by=>'GHALL'
);
end;
