'.dla-cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }',
'.dla-cards-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); margin-top: 16px; }',
'.dla-card { position: relative; display: flex; flex-direction: column; gap: 2px; padding: 16px 18px; border: 1px solid rgba(0,0,0,.1); border-left: 4px solid #8a8a8a; border-radius: 8px; background: #fff; color: inherit; text-decoration: none; transi'
||'tion: box-shadow .15s, transform .15s; }',
'.dla-card:hover { box-shadow: 0 6px 16px rgba(0,0,0,.08); transform: translateY(-1px); text-decoration: none; }',
'.dla-good { border-left-color: #2E7D32; } .dla-wait { border-left-color: #E65100; } .dla-bad { border-left-color: #C62828; }',
'.dla-card .dla-card-icon { position: absolute !important; top: 16px !important; right: 18px !important; left: auto !important; font-size: 22px; opacity: .45; }',
'.dla-card-num { font-size: 32px; font-weight: 600; line-height: 1.1; }',
