wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(63239841274656506)
,p_name=>'Documents'
,p_static_id=>'documents'
,p_region_name=>'documents'
,p_template=>4073835273271169698
,p_display_sequence=>20
,p_icon_css_classes=>'fa-file-text-o'
,p_region_template_options=>'#DEFAULT#:t-Region--showIcon:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDef:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* ============================================================',
'   Query   : Documents and their reads (page 2)',
'   Purpose : One row per read of each uploaded document, newest',
'             first. A document not yet read still shows.',
'             READ_STATUS says in plain words where the read is.',
'             SECONDS counts up live while the model is reading',
'             and shows the final time once it is done.',
'             STATUS_BADGE (11/21/2026): the document''s status as a',
'             coloured badge, same colours on every page (CSS on',
'             page 0); Needs review and Loaded are links.',
'   UPLOADED_ON is stored in UTC (database time) and',
'             shown here in US Central time.',
'   ============================================================ */',
'SELECT d.document_id,',
'       d.file_name,',
'       d.status                    AS document_status,',
'       CASE',
'           WHEN d.status = ''LOADED''    THEN ''dla-b dla-b-loaded''',
'           WHEN d.status = ''APPROVED''  THEN ''dla-b dla-b-loaded''',
'           WHEN d.status = ''IN_REVIEW'' THEN ''dla-b dla-b-review''',
'           WHEN d.status = ''REJECTED''  THEN ''dla-b dla-b-rejected''',
'           WHEN d.status = ''ERROR''     THEN ''dla-b dla-b-error''',
'           ELSE ''dla-b dla-b-reading''',
'       END                         AS status_class,',
'       CASE',
'           WHEN d.status = ''LOADED''    THEN ''<span class="fa fa-check-circle" aria-hidden="true"></span>Loaded''',
'           WHEN d.status = ''APPROVED''  THEN ''<span class="fa fa-check-circle" aria-hidden="true"></span>Approved''',
'           WHEN d.status = ''IN_REVIEW'' THEN ''<span class="fa fa-exclamation-triangle" aria-hidden="true"></span>Needs review <span class="fa fa-arrow-right" aria-hidden="true"></span>''',
'           WHEN d.status = ''REJECTED''  THEN ''<span class="fa fa-ban" aria-hidden="true"></span>Rejected''',
'           WHEN d.status = ''ERROR''     THEN ''<span class="fa fa-times" aria-hidden="true"></span>Error''',
'           ELSE ''<span class="fa fa-refresh" aria-hidden="true"></span>Being read''',
'       END                         AS status_label,',
'       CASE',
'           WHEN d.status = ''IN_REVIEW''',
'           THEN APEX_PAGE.GET_URL(p_page => 3, p_items => ''P3_STG_HEADER_ID'',',
'                    p_values => (SELECT MAX(h.stg_header_id) FROM dla_stg_headers h',
'                                 WHERE h.document_id = d.document_id AND h.review_status = ''PENDING''))',
'           WHEN d.status = ''LOADED''',
'           THEN APEX_PAGE.GET_URL(p_page => 5, p_items => ''P5_INVOICE_ID'',',
'                    p_values => (SELECT MAX(i.invoice_id) FROM dla_invoices i WHERE i.document_id = d.document_id))',
'       END                         AS status_link,',
'       d.uploaded_by,',
'       CAST(FROM_TZ(CAST(d.uploaded_on AS TIMESTAMP), ''UTC'')',
'            AT TIME ZONE ''America/Chicago'' AS DATE) AS uploaded_on,',
'       e.model_name,',
'       CASE e.status',
'           WHEN ''PENDING'' THEN ''Waiting for the relay''',
'           WHEN ''RUNNING'' THEN ''Reading now''',
'           WHEN ''SUCCESS'' THEN ''Read OK''',
'           WHEN ''ERROR''   THEN ''Read failed''',
'       END                         AS read_status,',
'       CASE e.status',
'           WHEN ''PENDING'' THEN ''fa-clock-o''',
'           WHEN ''RUNNING'' THEN ''fa-refresh fa-anim-spin''',
'           WHEN ''SUCCESS'' THEN ''fa-check''',
'           WHEN ''ERROR''   THEN ''fa-exclamation-triangle u-danger-text''',
'       END                         AS status_icon,',
'       CASE',
'           WHEN e.status = ''RUNNING''',
'           THEN ROUND((CAST(SYSTIMESTAMP AS DATE) - CAST(e.started_on AS DATE)) * 86400)',
'           ELSE ROUND(e.elapsed_ms / 1000)',
'       END                         AS seconds,',
'       e.error_message',
'FROM   dla_documents   d,',
'       dla_extractions e',
'WHERE  e.document_id (+) = d.document_id',
'ORDER  BY d.document_id DESC,',
'          e.extraction_id DESC'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No invoices have been uploaded yet.'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
