wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(63263042621729806)
,p_name=>'Problems found'
,p_static_id=>'problems-found'
,p_parent_plug_id=>wwv_flow_imp.id(63243190926656539)
,p_template=>4073835273271169698
,p_display_sequence=>10
,p_icon_css_classes=>'fa-exclamation-triangle'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* ------------------------------------------------------------',
'   Query   : Problems found (page 3)',
'   Purpose : The checks that stopped this invoice, one row each.',
'             SEVERITY_CLASS / SEVERITY_ICON (11/21/2026): the',
'             severity as a badge, same colours as every other',
'             page (CSS on page 0). Error is red, anything else',
'             (a warning) is orange.',
'   ------------------------------------------------------------ */',
'SELECT f.flag_id,',
'       f.severity,',
'       CASE WHEN f.severity = ''ERROR'' THEN ''dla-b dla-b-error''',
'            ELSE ''dla-b dla-b-review'' END              AS severity_class,',
'       CASE WHEN f.severity = ''ERROR'' THEN ''fa-times''',
'            ELSE ''fa-exclamation-triangle'' END         AS severity_icon,',
'       INITCAP(f.severity)                              AS severity_label,',
'       f.field_name,',
'       f.message,',
'       f.flag_source',
'FROM   dla_stg_flags f',
'WHERE  f.stg_header_id = :P3_STG_HEADER_ID'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P3_STG_HEADER_ID'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No problems. This invoice can be approved.'
,p_query_num_rows_type=>'ROWS_X_TO_Y'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20261120045039Z')
,p_updated_on=>wwv_flow_imp.dz('20261121202306Z')
