,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select h.stg_header_id,',
'       h.document_id,',
'       d.file_name,',
'       h.vendor_name,',
'       h.invoice_number,',
'       h.invoice_date,',
'       h.total,',
'       (select count(*)',
'          from dla_stg_flags f',
'         where f.stg_header_id = h.stg_header_id',
'           and f.severity = ''ERROR'') as error_flags,',
'       (select listagg(f.message, '' '') within group (order by f.flag_id)',
'          from dla_stg_flags f',
'         where f.stg_header_id = h.stg_header_id) as why_stopped,',
'       h.created_on',
'  from dla_stg_headers h,',
'       dla_documents   d',
' where d.document_id    = h.document_id',
'   and h.review_status  = ''PENDING'''))
