wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63545339666822240)
,p_process_sequence=>5
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Add the vendor to the vendor list'
,p_static_id=>'add-the-vendor-to-the-vendor-list'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* ------------------------------------------------------------',
'   Process : Add the vendor to the vendor list (11/21/2026)',
'   Button  : ADD_VENDOR (shown only while P3_VENDOR_ID is empty)',
'   Purpose : The vendor the model read is not in DLA_VENDORS.',
'             Add it, or switch it back on if it is there but',
'             inactive, pick it for this invoice, and log it.',
'             The process "Save the corrections and run the',
'             checks again" runs next (its request list includes',
'             ADD_VENDOR), so the flags are checked again.',
'   ------------------------------------------------------------ */',
'DECLARE',
'    l_vendor_id  dla_vendors.vendor_id%TYPE;',
'    l_name       dla_vendors.vendor_name%TYPE := TRIM(:P3_VENDOR_NAME);',
'BEGIN',
'    IF l_name IS NULL THEN',
'        RAISE_APPLICATION_ERROR(-20096, ''There is no vendor name to add.'');',
'    END IF;',
'',
'    BEGIN',
'        SELECT v.vendor_id',
'        INTO   l_vendor_id',
'        FROM   dla_vendors v',
'        WHERE  UPPER(TRIM(v.vendor_name)) = UPPER(l_name);',
'',
'        UPDATE dla_vendors v',
'        SET    v.active_yn = ''Y''',
'        WHERE  v.vendor_id = l_vendor_id;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            INSERT INTO dla_vendors (vendor_name)',
'            VALUES (l_name)',
'            RETURNING vendor_id INTO l_vendor_id;',
'    END;',
'',
'    :P3_VENDOR_ID := l_vendor_id;',
'',
'    dla_pkg.log_audit(''VENDOR_ADDED'',',
'                      ''Vendor "'' || l_name || ''" added to the vendor list from the review page.'',',
'                      TO_NUMBER(:P3_DOCUMENT_ID));',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(63545280906822239)
,p_process_success_message=>'Added "&P3_VENDOR_NAME." to the vendor list.'
,p_internal_uid=>63545339666822240
,p_created_on=>wwv_flow_imp.dz('20261121224111Z')
,p_updated_on=>wwv_flow_imp.dz('20261121230456Z')
,p_created_by=>'GHALL'
,p_updated_by=>'GHALL'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63264490667729820)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Approve and load the invoice'
,p_static_id=>'approve-and-load-the-invoice'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* A person approves a stopped invoice. Approval needs zero ERROR',
'   flags: the reviewer fixes the fields first, or rejects it. The',
'   database still decides: LOAD_INVOICE checks the status again. */',
'declare',
'    l_errors      number;',
'    l_invoice_id  number;',
'begin',
'    select count(*)',
'      into l_errors',
'      from dla_stg_flags f',
'     where f.stg_header_id = :P3_STG_HEADER_ID',
'       and f.severity      = ''ERROR'';',
'',
'    if l_errors > 0 then',
'        raise_application_error(',
'            -20080,',
'            ''This invoice still has '' || l_errors',
'            || '' problem(s). Fix the fields and click Save and check again, or reject it.''',
'        );',
'    end if;',
'',
'    update dla_stg_headers h',
'       set h.review_status = ''APPROVED'',',
'           h.reviewed_by   = :APP_USER,',
'           h.reviewed_on   = sysdate',
'     where h.stg_header_id = :P3_STG_HEADER_ID;',
'',
'    dla_pkg.log_audit(',
'        p_action      => ''APPROVED'',',
'        p_details     => ''Reviewer '' || :APP_USER || '' approved staged invoice '' || :P3_STG_HEADER_ID || ''.'',',
'        p_document_id => :P3_DOCUMENT_ID',
'    );',
'',
'    l_invoice_id := dla_pkg.load_invoice(:P3_STG_HEADER_ID);',
'',
'    :P3_STG_HEADER_ID := null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(63262695534729802)
,p_process_success_message=>'Approved. The invoice has been loaded.'
,p_internal_uid=>63264490667729820
,p_created_on=>wwv_flow_imp.dz('20261120045040Z')
,p_updated_on=>wwv_flow_imp.dz('20261121224112Z')
,p_created_by=>'GHALL'
,p_updated_by=>'GHALL'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63264278011729818)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load the staged invoice'
,p_static_id=>'load-the-staged-invoice'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Fill the fields from the staged invoice the reviewer opened. */',
'declare',
'    l_h  dla_stg_headers%rowtype;',
'begin',
'    select h.*',
'      into l_h',
'      from dla_stg_headers h',
'     where h.stg_header_id = :P3_STG_HEADER_ID;',
'',
'    :P3_DOCUMENT_ID    := l_h.document_id;',
'    :P3_VENDOR_NAME    := l_h.vendor_name;',
'    :P3_VENDOR_ID      := l_h.vendor_id;',
'    :P3_INVOICE_NUMBER := l_h.invoice_number;',
'    :P3_INVOICE_DATE   := to_char(l_h.invoice_date, ''MM/DD/YYYY'');',
'    :P3_DUE_DATE       := to_char(l_h.due_date, ''MM/DD/YYYY'');',
'    :P3_SUBTOTAL       := l_h.subtotal;',
'    :P3_TAX            := l_h.tax;',
'    :P3_TOTAL          := l_h.total;',
'    :P3_REVIEW_COMMENT := l_h.review_comment;',
'',
'    select d.file_name',
'      into :P3_FILE_NAME',
'      from dla_documents d',
'     where d.document_id = l_h.document_id;',
'exception',
'    when no_data_found then',
'        :P3_STG_HEADER_ID := null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P3_STG_HEADER_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>63264278011729818
,p_created_on=>wwv_flow_imp.dz('20261120045039Z')
,p_updated_on=>wwv_flow_imp.dz('20261120045039Z')
,p_created_by=>'GHALL'
,p_updated_by=>'GHALL'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63264521919729821)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Reject the invoice'
,p_static_id=>'reject-the-invoice'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* A person rejects a stopped invoice. Nothing is loaded. */',
'begin',
'    update dla_stg_headers h',
'       set h.review_status  = ''REJECTED'',',
'           h.reviewed_by    = :APP_USER,',
'           h.reviewed_on    = sysdate,',
'           h.review_comment = :P3_REVIEW_COMMENT',
'     where h.stg_header_id = :P3_STG_HEADER_ID;',
'',
'    update dla_documents d',
'       set d.status = ''REJECTED''',
'     where d.document_id = :P3_DOCUMENT_ID;',
'',
'    dla_pkg.log_audit(',
'        p_action      => ''REJECTED'',',
'        p_details     => ''Reviewer '' || :APP_USER || '' rejected staged invoice '' || :P3_STG_HEADER_ID',
'                         || case when :P3_REVIEW_COMMENT is not null then '': '' || :P3_REVIEW_COMMENT end,',
'        p_document_id => :P3_DOCUMENT_ID',
'    );',
'',
'    :P3_STG_HEADER_ID := null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(63262824875729804)
,p_process_success_message=>'Rejected. The document is marked REJECTED.'
,p_internal_uid=>63264521919729821
,p_created_on=>wwv_flow_imp.dz('20261120045040Z')
,p_updated_on=>wwv_flow_imp.dz('20261121224112Z')
,p_created_by=>'GHALL'
,p_updated_by=>'GHALL'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63264357397729819)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save the corrections and run the checks again'
,p_static_id=>'save-the-corrections-and-run-the-checks-again'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Write the reviewer''s corrections to the staged invoice, then',
'   run DLA_PKG.VALIDATE_STAGING again so the flags match the',
'   corrected values. VENDOR_NAME is left as the model read it;',
'   the reviewer''s choice goes in VENDOR_ID, which is what',
'   LOAD_INVOICE uses. */',
'begin',
'    update dla_stg_headers h',
'       set h.vendor_id      = :P3_VENDOR_ID,',
'           h.invoice_number = :P3_INVOICE_NUMBER,',
'           h.invoice_date   = to_date(:P3_INVOICE_DATE, ''MM/DD/YYYY''),',
'           h.due_date       = to_date(:P3_DUE_DATE, ''MM/DD/YYYY''),',
'           h.subtotal       = to_number(:P3_SUBTOTAL),',
'           h.tax            = to_number(:P3_TAX),',
'           h.total          = to_number(:P3_TOTAL),',
'           h.review_comment = :P3_REVIEW_COMMENT',
'     where h.stg_header_id = :P3_STG_HEADER_ID;',
'',
'    dla_pkg.validate_staging(:P3_STG_HEADER_ID);',
'',
'    dla_pkg.log_audit(',
'        p_action      => ''REVIEWED'',',
'        p_details     => ''Reviewer '' || :APP_USER || '' saved staged invoice ''',
'                         || :P3_STG_HEADER_ID || '' and the checks were run again.'',',
'        p_document_id => :P3_DOCUMENT_ID',
'    );',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,APPROVE,ADD_VENDOR'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>'Saved. The checks were run again.'
,p_internal_uid=>63264357397729819
,p_created_on=>wwv_flow_imp.dz('20261120045039Z')
,p_updated_on=>wwv_flow_imp.dz('20261121224112Z')
,p_created_by=>'GHALL'
,p_updated_by=>'GHALL'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63264687691729822)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SHOW_DOCUMENT'
,p_static_id=>'show-document'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Ajax callback. Streams the uploaded file (PDF or image) from',
'   DLA_DOCUMENTS so the page can show it in a frame. x01 is the',
'   DOCUMENT_ID. */',
'declare',
'    l_blob  dla_documents.file_blob%type;',
'    l_mime  dla_documents.mime_type%type;',
'    l_name  dla_documents.file_name%type;',
'begin',
'    select d.file_blob, d.mime_type, d.file_name',
'      into l_blob, l_mime, l_name',
'      from dla_documents d',
'     where d.document_id = to_number(apex_application.g_x01);',
'',
'    sys.htp.init;',
'    sys.owa_util.mime_header(l_mime, false);',
'    sys.htp.p(''Content-Length: '' || dbms_lob.getlength(l_blob));',
'    sys.htp.p(''Content-Disposition: inline; filename="'' || l_name || ''"'');',
'    sys.owa_util.http_header_close;',
'    sys.wpg_docload.download_file(l_blob);',
'    apex_application.stop_apex_engine;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>63264687691729822
,p_created_on=>wwv_flow_imp.dz('20261120045040Z')
,p_updated_on=>wwv_flow_imp.dz('20261120045040Z')
,p_created_by=>'GHALL'
,p_updated_by=>'GHALL'
);
end;
