wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(63499258764519429)
,p_name=>'What each model read'
,p_static_id=>'dla-p4-fields'
,p_parent_plug_id=>wwv_flow_imp.id(63496998212519406)
,p_template=>4073835273271169698
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Page 4: latest read by each model, one row per field.    AGREEMENT_CLASS / AGREEMENT_ICON (11/21/2026): Same or',
'   Different as a badge, same colours as every other page',
'   (CSS on page 0). Blank rows get no badge.',
'*/',
'SELECT x.*,',
'       CASE x.agreement WHEN ''Same''      THEN ''dla-b dla-b-loaded''',
'                        WHEN ''Different'' THEN ''dla-b dla-b-error'' END AS agreement_class,',
'       CASE x.agreement WHEN ''Same''      THEN ''fa fa-check-circle''',
'                        WHEN ''Different'' THEN ''fa fa-times'' END        AS agreement_icon',
'FROM  (',
'WITH latest AS (',
' SELECT e.model_code, MAX(e.extraction_id) AS extraction_id',
' FROM dla_extractions e',
' WHERE e.document_id = :P4_DOCUMENT_ID',
' GROUP BY e.model_code),',
'v AS (',
' SELECT e.model_code, e.model_name, e.status, e.elapsed_ms, e.error_message,',
' jt.vendor_name, jt.invoice_number, jt.invoice_date, jt.due_date,',
' NVL(TO_CHAR(TO_NUMBER(REPLACE(jt.subtotal, '','', '''') DEFAULT NULL ON CONVERSION ERROR), ''FM999G999G990D00''), jt.subtotal) AS subtotal,',
' NVL(TO_CHAR(TO_NUMBER(REPLACE(jt.tax, '','', '''') DEFAULT NULL ON CONVERSION ERROR), ''FM999G999G990D00''), jt.tax) AS tax,',
' NVL(TO_CHAR(TO_NUMBER(REPLACE(jt.total, '','', '''') DEFAULT NULL ON CONVERSION ERROR), ''FM999G999G990D00''), jt.total) AS total,',
' (SELECT COUNT(*) FROM JSON_TABLE(NVL(e.extracted_json, ''{}''), ''$.line_items[*]'' COLUMNS (seq FOR ORDINALITY)) x) AS line_count,',
' (SELECT LISTAGG(f.message, '' | '') WITHIN GROUP (ORDER BY f.flag_id)',
'  FROM dla_stg_headers h, dla_stg_flags f',
'  WHERE h.extraction_id = e.extraction_id AND f.stg_header_id = h.stg_header_id AND f.severity = ''ERROR'') AS problems,',
' (SELECT COUNT(*) FROM dla_stg_headers h WHERE h.extraction_id = e.extraction_id) AS staged',
' FROM dla_extractions e, latest l,',
' JSON_TABLE(NVL(e.extracted_json, ''{}''), ''$'' COLUMNS (',
'  vendor_name VARCHAR2(200) PATH ''$.vendor_name'', invoice_number VARCHAR2(100) PATH ''$.invoice_number'',',
'  invoice_date VARCHAR2(100) PATH ''$.invoice_date'', due_date VARCHAR2(100) PATH ''$.due_date'',',
'  subtotal VARCHAR2(100) PATH ''$.subtotal'', tax VARCHAR2(100) PATH ''$.tax'', total VARCHAR2(100) PATH ''$.total'')) jt',
' WHERE e.extraction_id = l.extraction_id),',
'f AS (',
' SELECT 1 AS seq, ''Model'' AS field_name FROM dual UNION ALL SELECT 2, ''Read status'' FROM dual UNION ALL',
' SELECT 3, ''Seconds'' FROM dual UNION ALL SELECT 4, ''Vendor'' FROM dual UNION ALL',
' SELECT 5, ''Invoice number'' FROM dual UNION ALL SELECT 6, ''Invoice date'' FROM dual UNION ALL',
' SELECT 7, ''Due date'' FROM dual UNION ALL SELECT 8, ''Subtotal'' FROM dual UNION ALL',
' SELECT 9, ''Tax'' FROM dual UNION ALL SELECT 10, ''Total'' FROM dual UNION ALL',
' SELECT 11, ''Lines read'' FROM dual UNION ALL SELECT 12, ''Problems found by the checks'' FROM dual),',
'p AS (',
' SELECT f.seq, f.field_name, v.model_code, CASE WHEN v.status = ''SUCCESS'' THEN 1 ELSE 0 END AS ok,',
' CASE f.seq',
'  WHEN 1 THEN v.model_name',
'  WHEN 2 THEN CASE v.status WHEN ''SUCCESS'' THEN ''Read OK'' WHEN ''RUNNING'' THEN ''Reading now'' WHEN ''PENDING'' THEN ''Waiting for the relay'' WHEN ''ERROR'' THEN ''Read failed: '' || v.error_message ELSE v.status END',
'  WHEN 3 THEN TO_CHAR(ROUND(v.elapsed_ms / 1000, 1))',
'  WHEN 4 THEN v.vendor_name WHEN 5 THEN v.invoice_number WHEN 6 THEN v.invoice_date WHEN 7 THEN v.due_date',
'  WHEN 8 THEN v.subtotal WHEN 9 THEN v.tax WHEN 10 THEN v.total',
'  WHEN 11 THEN TO_CHAR(v.line_count)',
'  WHEN 12 THEN CASE WHEN v.staged = 0 THEN ''(compare read: not checked)'' ELSE NVL(v.problems, ''None'') END',
' END AS val',
' FROM f, v)',
'SELECT p.seq, p.field_name,',
' MAX(CASE WHEN p.model_code = ''OLLAMA'' THEN p.val END) AS local_model,',
' MAX(CASE WHEN p.model_code = ''OCI_GENAI'' THEN p.val END) AS oci_model,',
' CASE WHEN p.seq IN (1, 2, 3, 12) THEN NULL',
'  WHEN COUNT(DISTINCT p.model_code) < 2 THEN NULL',
'  WHEN MIN(p.ok) = 0 THEN NULL',
'  WHEN NVL(MAX(CASE WHEN p.model_code = ''OLLAMA'' THEN p.val END), ''~'') = NVL(MAX(CASE WHEN p.model_code = ''OCI_GENAI'' THEN p.val END), ''~'') THEN ''Same''',
'  ELSE ''Different'' END AS agreement',
'FROM p',
'GROUP BY p.seq, p.field_name',
'      ) x'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P4_DOCUMENT_ID'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'Pick an invoice above. No read of it yet: click Read with both models.'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20261121191533Z')
,p_updated_on=>wwv_flow_imp.dz('20261121205914Z')
,p_created_by=>'GHALL'
,p_updated_by=>'GHALL'
);
