'/* Page 5: the chosen invoice, one row shown as label/value pairs. Read-only. */',
'SELECT v.vendor_name                              AS vendor,',
'       i.invoice_number                           AS invoice_number,',
'       TO_CHAR(i.invoice_date, ''MM/DD/YYYY'')      AS invoice_date,',
'       TO_CHAR(i.due_date, ''MM/DD/YYYY'')          AS due_date,',
'       TO_CHAR(i.subtotal, ''FM999G999G990D00'')    AS subtotal,',
'       TO_CHAR(i.tax, ''FM999G999G990D00'')         AS tax,',
'       TO_CHAR(i.total, ''FM999G999G990D00'')       AS total,',
'       i.loaded_by                                AS loaded_by,',
'       TO_CHAR(i.loaded_on, ''MM/DD/YYYY HH24:MI'') AS loaded_on,',
'       d.file_name                                AS from_file',
'FROM   dla_invoices  i,',
'       dla_vendors   v,',
'       dla_documents d',
'WHERE  i.invoice_id  = :P5_INVOICE_ID',
'AND    v.vendor_id   = i.vendor_id',
'AND    d.document_id = i.document_id'))
