wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63545623437822243)
,p_process_sequence=>5
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Forget an invoice that no longer exists'
,p_static_id=>'forget-an-invoice-that-no-longer-exists'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* ------------------------------------------------------------',
'   Process : Forget an invoice that no longer exists (11/21/2026)',
'   Purpose : P5_INVOICE_ID is kept in the session. After a demo',
'             reset the invoice it points at is gone, and the page',
'             showed ORA-01403 instead of the list. If the invoice',
'             is not in DLA_INVOICES, clear the item so the list',
'             shows. Read-only apart from the page item.',
'   ------------------------------------------------------------ */',
'DECLARE',
'    l_count NUMBER;',
'BEGIN',
'    IF :P5_INVOICE_ID IS NOT NULL THEN',
'        SELECT COUNT(*)',
'        INTO   l_count',
'        FROM   dla_invoices i',
'        WHERE  i.invoice_id = TO_NUMBER(:P5_INVOICE_ID);',
'',
'        IF l_count = 0 THEN',
'            :P5_INVOICE_ID := NULL;',
'        END IF;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>63545623437822243
,p_created_on=>wwv_flow_imp.dz('20261121233703Z')
,p_updated_on=>wwv_flow_imp.dz('20261121233703Z')
,p_created_by=>'GHALL'
,p_updated_by=>'GHALL'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(63542427872822211)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SHOW_DOCUMENT'
,p_static_id=>'show-document'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Page 5, Ajax callback SHOW_DOCUMENT: streams the file behind the',
'   chosen invoice into the iframe on the left. x01 = INVOICE_ID. */',
'DECLARE',
'    l_blob  BLOB;',
'    l_mime  VARCHAR2(255);',
'    l_name  VARCHAR2(400);',
'BEGIN',
'    SELECT d.file_blob, d.mime_type, d.file_name',
'    INTO   l_blob, l_mime, l_name',
'    FROM   dla_documents d,',
'           dla_invoices  i',
'    WHERE  i.invoice_id  = TO_NUMBER(apex_application.g_x01)',
'    AND    d.document_id = i.document_id;',
'',
'    sys.htp.init;',
'    sys.owa_util.mime_header(l_mime, FALSE);',
'    sys.htp.p(''Content-Length: '' || DBMS_LOB.GETLENGTH(l_blob));',
'    sys.htp.p(''Content-Disposition: inline; filename="'' || l_name || ''"'');',
'    sys.owa_util.http_header_close;',
'    sys.wpg_docload.download_file(l_blob);',
'    apex_application.stop_apex_engine;',
'EXCEPTION',
'    WHEN apex_application.e_stop_apex_engine THEN',
'        NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>63542427872822211
,p_created_on=>wwv_flow_imp.dz('20261121195703Z')
,p_updated_on=>wwv_flow_imp.dz('20261121195703Z')
,p_created_by=>'GHALL'
,p_updated_by=>'GHALL'
);
end;
/
